const CSS=".card{box-sizing:border-box;width:100%;height:100%;min-width:0;min-height:0;padding:8px;display:flex;flex-direction:column;gap:6px;overflow:hidden;background:transparent;color:var(--ink);font:13px/1.4 system-ui,-apple-system,\"PingFang SC\",\"Microsoft YaHei\",sans-serif}\n.card *{box-sizing:border-box}\n.card[data-size=\"3x3\"]{padding:6px;gap:5px}\n\n.head{display:flex;align-items:center;gap:6px;flex:0 0 auto;min-width:0}\n.name{flex:1;min-width:0;font-size:14px;font-weight:700;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.chip{flex:0 0 auto;font-size:11px;color:var(--muted);border:1px solid var(--line);border-radius:999px;padding:1px 8px}\n\n.tabs{display:flex;gap:4px;padding:2px;background:var(--soft);border-radius:9px;flex:0 0 auto}\n.tab{flex:1;min-width:0;height:24px;border:0;border-radius:7px;background:transparent;color:var(--muted);font:inherit;font-size:12px;cursor:pointer}\n.tab[aria-pressed=\"true\"]{background:var(--accent);color:var(--on-accent);font-weight:600}\n\n.body{flex:1;min-height:0;min-width:0;display:flex;flex-direction:column;gap:8px}\n.card[data-size=\"6x3\"] .body{flex-direction:row}\n.pane{min-width:0;min-height:0;display:flex;flex-direction:column;gap:6px;padding:8px;background:var(--panel-paper);border:1px solid var(--line);border-radius:12px}\n.card[data-size=\"3x3\"] .pane{padding:6px;border-radius:10px}\n.form{flex:0 0 auto}\n.results{flex:1 1 0}\n.card[data-size=\"3x3\"] .form{flex:1 1 0}\n.card[data-size=\"6x3\"] .form{flex:0 0 46%}\n\n.fields{display:flex;flex-direction:column;gap:6px;min-height:0;overflow:auto;flex:1 1 auto}\n.card[data-size=\"6x6\"] .fields{display:grid;grid-template-columns:1fr 1fr;gap:8px 10px;overflow:visible}\n.card[data-size=\"3x3\"] .form,.card[data-size=\"6x3\"] .form{overflow:hidden}\n.fld{display:flex;flex-direction:column;gap:2px;min-width:0}\n.lab{font-size:11px;line-height:1.2;color:var(--muted)}\n.hint{font-size:11px;line-height:1.2;color:var(--ink);font-weight:600}\n.hint